import React, { useEffect, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Church, Menu, X, Sun, Moon } from 'lucide-react';

const navItems = [
  { name: 'Home', path: '/' },
  { name: 'About', path: '/about' },
  { name: 'Services', path: '/services' },
  { name: 'Events', path: '/events' },
  { name: 'Sermons', path: '/sermons' },
  { name: 'Giving', path: '/giving' },
  { name: 'Connect', path: '/connect' },
];

export const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = React.useState(false);
  const [isDark, setIsDark] = useState(true);
  const location = useLocation();

  useEffect(() => {
    const root = window.document.documentElement;
    if (isDark) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [isDark]);

  const toggleTheme = () => setIsDark(!isDark);

  return (
    <nav className="fixed top-6 left-1/2 -translate-x-1/2 z-50 w-[90%] max-w-6xl">
      <div className="bg-white/40 dark:bg-black/20 backdrop-blur-xl border border-black/5 dark:border-white/20 rounded-2xl px-6 py-3 flex items-center justify-between shadow-2xl relative z-20 transition-colors duration-500">
        <Link to="/" className="flex items-center gap-2 group">
          <div className="p-2 bg-blue-500/20 rounded-xl group-hover:bg-blue-500/30 transition-colors">
            <Church className="text-blue-600 dark:text-white w-6 h-6" />
          </div>
          <span className="text-black dark:text-white font-bold text-lg tracking-tight">Lighthouse Gospel</span>
        </Link>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center gap-1">
          {navItems.map((item) => (
            <Link
              key={item.path}
              to={item.path}
              className={`px-4 py-2 rounded-xl transition-all duration-200 text-sm font-medium
                ${location.pathname === item.path 
                  ? 'bg-black/10 dark:bg-white/20 text-black dark:text-white shadow-inner' 
                  : 'text-black/60 dark:text-white/70 hover:text-black dark:hover:text-white hover:bg-black/5 dark:hover:bg-white/10'}`}
            >
              {item.name}
            </Link>
          ))}

          <button 
            onClick={toggleTheme}
            className="ml-2 p-2 rounded-xl text-black/60 dark:text-white/70 hover:bg-black/5 dark:hover:bg-white/10 transition-all duration-300"
            aria-label="Toggle theme"
          >
            {isDark ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>

        <div className="flex items-center gap-2 md:hidden">
           <button 
            onClick={toggleTheme}
            className="p-2 rounded-xl text-black/60 dark:text-white/70 hover:bg-black/5 dark:hover:bg-white/10 transition-all"
          >
