        className={`md:hidden absolute top-0 left-0 right-0 pt-20 pb-4 px-4 bg-white/90 dark:bg-black/80 backdrop-blur-3xl border border-black/5 dark:border-white/10 rounded-2xl shadow-2xl transition-all duration-500 ease-apple origin-top
          ${isOpen 
            ? 'opacity-100 translate-y-0 scale-100 pointer-events-auto' 
            : 'opacity-0 -translate-y-4 scale-95 pointer-events-none'}`}
      >
        <div className="flex flex-col gap-1">
          {navItems.map((item, index) => (
            <Link
              key={item.path}
              to={item.path}
              onClick={() => setIsOpen(false)}
              style={{ transitionDelay: isOpen ? `${index * 40}ms` : '0ms' }}
              className={`px-4 py-3 rounded-xl transition-all duration-300 transform
                ${isOpen ? 'translate-x-0 opacity-100' : '-translate-x-4 opacity-0'}
                ${location.pathname === item.path 
                  ? 'bg-black/5 dark:bg-white/20 text-black dark:text-white font-semibold' 
                  : 'text-black/60 dark:text-white/70 hover:text-black dark:hover:text-white hover:bg-black/5 dark:hover:bg-white/10'}`}
            >
              {item.name}
            </Link>
          ))}
        </div>
      </div>
    </nav>
  );
};

