export const Sermons: React.FC = () => {
  const [activeSermon, setActiveSermon] = useState<SermonData | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [playbackSpeed, setPlaybackSpeed] = useState(1);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const formatTime = (time: number) => {
    if (isNaN(time)) return "0:00";
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  useEffect(() => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.play().catch(() => setIsPlaying(false));
      } else {
        audioRef.current.pause();
      }
    }
  }, [isPlaying, activeSermon]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.playbackRate = playbackSpeed;
    }
  }, [playbackSpeed]);

  const onTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
    }
  };

  const onLoadedMetadata = () => {
    if (audioRef.current) {
      setDuration(audioRef.current.duration);
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
    if (audioRef.current) {
      audioRef.current.currentTime = time;
    }
  };

  const skipTime = (amount: number) => {
    if (audioRef.current) {
      const newTime = Math.max(0, Math.min(audioRef.current.duration || 0, audioRef.current.currentTime + amount));
      audioRef.current.currentTime = newTime;
      setCurrentTime(newTime);
    }
  };

  const handleSermonToggle = (sermon: SermonData) => {
    if (activeSermon?.id === sermon.id) {
      setIsPlaying(!isPlaying);
    } else {
      setActiveSermon(sermon);
      setIsPlaying(true);
      setCurrentTime(0);
    }
  };

  return (
    <div className="pt-32 pb-40 px-6 max-w-7xl mx-auto space-y-12">
      <audio 
        ref={audioRef}
        src={activeSermon?.audioUrl}
        onTimeUpdate={onTimeUpdate}
        onLoadedMetadata={onLoadedMetadata}
        onEnded={() => setIsPlaying(false)}
      />

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-black/5 dark:border-white/5 pb-10">
        <div className="space-y-2">
          <div className="inline-flex items-center gap-2 px-3 py-1 bg-blue-500/10 rounded-full text-blue-600 dark:text-blue-400 text-[10px] font-black uppercase tracking-[0.2em] mb-2">
            <Headset size={12} /> Audio Sanctuary
          </div>
          <h1 className="text-5xl font-bold text-black dark:text-white tracking-tight">Sermon Library</h1>
          <p className="text-black/50 dark:text-white/50 max-w-lg">Listen to the latest messages from our teaching team.</p>
        </div>
        <div className="relative max-w-md w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-black/30 dark:text-white/30 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search topics..." 
            className="w-full bg-black/5 dark:bg-white/5 border border-black/10 dark:border-white/10 rounded-2xl py-4 pl-12 pr-4 text-black dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all backdrop-blur-md"
          />
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {sermons.map(sermon => (
          <GlassCard 
            key={sermon.id} 
            className={`group transition-all duration-500 ${activeSermon?.id === sermon.id ? 'ring-2 ring-blue-500/50 scale-[1.02]' : ''}`}
          >
            <div className="flex flex-col sm:flex-row gap-6">
              <div className={`relative w-full sm:w-40 aspect-square rounded-2xl bg-gradient-to-br ${sermon.color} border border-black/5 dark:border-white/10 flex items-center justify-center overflow-hidden shrink-0`}>
                <Mic2 className="text-black/20 dark:text-white/20 w-12 h-12 group-hover:scale-110 transition-transform duration-500" />

                {activeSermon?.id === sermon.id && isPlaying && (
                  <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex items-end gap-1 h-8">
                    {[0, 1, 2, 3, 4].map(i => (
                      <div 
                        key={i} 
                        className="w-1 bg-blue-500 rounded-full animate-bounce" 
                        style={{ 
                          height: `${40 + (i * 10)}%`,
                          animationDuration: `${0.8 + (i * 0.1)}s`,
                        }} 
                      />
                    ))}
                  </div>
                )}

                <button 
                  onClick={() => handleSermonToggle(sermon)}
                  className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <div className="w-14 h-14 bg-white dark:bg-black rounded-full shadow-2xl flex items-center justify-center text-black dark:text-white scale-90 group-hover:scale-100 transition-transform">
                    {activeSermon?.id === sermon.id && isPlaying ? (
                      <Pause className="fill-current" size={24} />
                    ) : (
                      <Play className="fill-current ml-1" size={24} />
                    )}
                  </div>
                </button>
              </div>

              <div className="flex-1 space-y-4">
                <div className="space-y-1">
                  <div className="flex justify-between items-start">
                    <span className="text-[10px] text-blue-600 dark:text-blue-400 font-black uppercase tracking-widest">{sermon.series}</span>
                    <span className="text-[10px] text-black/30 dark:text-white/30 font-bold">{sermon.duration}</span>
                  </div>
                  <h3 className="text-2xl font-bold text-black dark:text-white leading-tight group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                    {sermon.title}
                  </h3>
                  <p className="text-black/50 dark:text-white/50 font-medium text-sm">{sermon.speaker} • {sermon.date}</p>
                </div>
                <div className="flex flex-wrap gap-2">
                  <button className="flex items-center gap-2 px-4 py-2 bg-black/5 dark:bg-white/5 rounded-xl text-xs font-bold text-black/70 dark:text-white/70 hover:bg-black/10 dark:hover:bg-white/10 transition-all">
                    <BookOpen size={14} /> Notes
                  </button>
                  <button className="flex items-center gap-2 px-4 py-2 bg-black/5 dark:bg-white/5 rounded-xl text-xs font-bold text-black/70 dark:text-white/70 hover:bg-black/10 dark:hover:bg-white/10 transition-all">
                    <Download size={14} /> MP3
                  </button>
                  <button className="flex items-center gap-2 px-4 py-2 bg-black/5 dark:bg-white/5 rounded-xl text-xs font-bold text-black/70 dark:text-white/70 hover:bg-black/10 dark:hover:bg-white/10 transition-all">
                    <Share2 size={14} /> Share
                  </button>
                </div>
              </div>
            </div>
          </GlassCard>
        ))}
      </div>

      {activeSermon && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[90%] max-w-4xl z-50 transition-all duration-500 animate-apple-fade-in">
          <div className="relative group/player">
            <div className="absolute inset-0 bg-white/60 dark:bg-black/60 backdrop-blur-[32px] saturate-[200%] rounded-[28px] border border-white/40 dark:border-white/10 shadow-[0_32px_64px_rgba(0,0,0,0.2)] dark:shadow-[0_32px_64px_rgba(0,0,0,0.6)]" />
            <div className="relative p-4 md:p-6 flex flex-col md:flex-row items-center gap-4 md:gap-8">
              <div className="flex items-center gap-4 w-full md:w-auto min-w-0">
                <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${activeSermon.color} shrink-0 flex items-center justify-center border border-white/20`}>
                  <Mic2 size={18} className="text-white/80" />
                </div>
                <div className="min-w-0 flex-1">
                  <h4 className="font-bold text-black dark:text-white text-sm truncate">{activeSermon.title}</h4>
                  <p className="text-black/40 dark:text-white/40 text-[10px] uppercase font-black tracking-widest truncate">{activeSermon.speaker}</p>
                </div>
                <button onClick={() => setActiveSermon(null)} className="md:hidden p-2 text-black/40"><X size={20} /></button>
              </div>

              <div className="flex-1 w-full space-y-3">
                <div className="flex items-center gap-4">
                  <span className="text-[10px] font-mono text-black/40 dark:text-white/40 w-10 text-right">{formatTime(currentTime)}</span>
                  <input 
                    type="range"
                    min="0"
                    max={duration || 100}
                    value={currentTime}
                    onChange={handleSeek}
                    className="flex-1 h-1.5 bg-black/10 dark:bg-white/10 rounded-full appearance-none cursor-pointer accent-blue-600"
                  />
                  <span className="text-[10px] font-mono text-black/40 dark:text-white/40 w-10">{formatTime(duration)}</span>
                </div>

                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-6">
                    <button onClick={() => skipTime(-15)} className="text-black/60 dark:text-white/60 hover:text-blue-600"><SkipBack size={20} /></button>
                    <button onClick={() => setIsPlaying(!isPlaying)} className="w-12 h-12 bg-black dark:bg-white text-white dark:text-black rounded-full flex items-center justify-center hover:scale-110 transition-all">
                      {isPlaying ? <Pause size={22} className="fill-current" /> : <Play size={22} className="fill-current ml-1" />}
                    </button>
                    <button onClick={() => skipTime(15)} className="text-black/60 dark:text-white/60 hover:text-blue-600"><SkipForward size={20} /></button>
                  </div>
                  <div className="flex items-center gap-2">
                    {[1, 1.5, 2].map(speed => (
                      <button key={speed} onClick={() => setPlaybackSpeed(speed)} className={`px-2 py-1 rounded-lg text-[9px] font-black ${playbackSpeed === speed ? 'bg-blue-600 text-white' : 'text-black/40 dark:text-white/40'}`}>
                        {speed}x
                      </button>
                    ))}
                    <div className="h-4 w-[1px] bg-black/10 mx-2" />
                    <Volume2 size={16} className="text-black/40 dark:text-white/40" />
                  </div>
                </div>
              </div>
              <button onClick={() => setActiveSermon(null)} className="hidden md:block p-2 text-black/20 hover:text-red-500 transition-colors"><X size={20} /></button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

