      document.body.style.overflow = 'unset';
    }
  }, [isOpen]);

  const toggleTheme = () => setIsDark(!isDark);

  const handleInteractionEnd = (e: React.MouseEvent | React.TouchEvent) => {
    (e.currentTarget as HTMLElement).blur();
  };

