const AudioVisualizer: React.FC<{ isPlaying: boolean; audioRef: React.RefObject<HTMLAudioElement | null> }> = ({ isPlaying, audioRef }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>(0);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const dataArrayRef = useRef<Uint8Array | null>(null);
  const contextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (!audioRef.current || !canvasRef.current) return;

    const setupAudio = () => {
      if (!analyserRef.current && audioRef.current) {
        const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
        const context = new AudioContextClass();
        const analyser = context.createAnalyser();

        // Use crossOrigin to allow analysis of external URLs
        audioRef.current.crossOrigin = "anonymous";

        const source = context.createMediaElementSource(audioRef.current);
        source.connect(analyser);
        analyser.connect(context.destination);

        analyser.fftSize = 64;
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);

        contextRef.current = context;
        analyserRef.current = analyser;
        dataArrayRef.current = dataArray;
      }
    };

    const draw = () => {
      if (!canvasRef.current || !analyserRef.current || !dataArrayRef.current) return;

      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      analyserRef.current.getByteFrequencyData(dataArrayRef.current);

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const barCount = dataArrayRef.current.length / 2;
      const barWidth = (canvas.width / barCount) * 0.6;
      const barGap = (canvas.width / barCount) * 0.4;

      for (let i = 0; i < barCount; i++) {
        const barHeight = isPlaying 
          ? (dataArrayRef.current[i] / 255) * canvas.height * 0.8
          : 2; // Flat baseline when paused

        const x = i * (barWidth + barGap);
        const y = canvas.height - barHeight;

        // Create a nice gradient for each bar
        const gradient = ctx.createLinearGradient(0, y, 0, canvas.height);
        gradient.addColorStop(0, '#3b82f6'); // Blue-500
        gradient.addColorStop(1, '#8b5cf6'); // Purple-500

        ctx.fillStyle = gradient;
        ctx.beginPath();
        // Rounded corners top
        ctx.roundRect(x, y, barWidth, barHeight, [4, 4, 0, 0]);
        ctx.fill();
      }

      animationRef.current = requestAnimationFrame(draw);
    };

    if (isPlaying) {
      setupAudio();
      if (contextRef.current?.state === 'suspended') {
        contextRef.current.resume();
      }
      animationRef.current = requestAnimationFrame(draw);
    } else {
      cancelAnimationFrame(animationRef.current);
      // Still draw one last frame to show baseline
      draw();
    }

    return () => cancelAnimationFrame(animationRef.current);
  }, [isPlaying, audioRef]);

  return (
    <canvas 
      ref={canvasRef} 
      width={120} 
      height={32} 
      className="opacity-60 group-hover:opacity-100 transition-opacity"
    />
  );
};

export const Sermons: React.FC = () => {
  const [activeSermon, setActiveSermon] = useState<SermonData | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [playbackSpeed, setPlaybackSpeed] = useState(1);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const formatTime = (time: number) => {
    if (isNaN(time) || !isFinite(time)) return "0:00";
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
