const AudioVisualizer: React.FC<{ isPlaying: boolean; audioRef: React.RefObject<HTMLAudioElement | null>; color?: string }> = ({ isPlaying, audioRef, color = '#3b82f6' }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>(0);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const dataArrayRef = useRef<Uint8Array | null>(null);
  const contextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (!audioRef.current || !canvasRef.current) return;

    const setupAudio = () => {
      if (!analyserRef.current && audioRef.current) {
        try {
          const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
          const context = new AudioContextClass();
          const analyser = context.createAnalyser();

          // Use crossOrigin to allow analysis of external URLs
          audioRef.current.crossOrigin = "anonymous";

          const source = context.createMediaElementSource(audioRef.current);
          source.connect(analyser);
          analyser.connect(context.destination);

          analyser.fftSize = 128; // Increased for a more detailed look
          const bufferLength = analyser.frequencyBinCount;
          const dataArray = new Uint8Array(bufferLength);

          contextRef.current = context;
          analyserRef.current = analyser;
          dataArrayRef.current = dataArray;
        } catch (e) {
          console.warn("Audio Context setup failed (likely cross-origin or gesture restriction)", e);
        }
      }
    };

    const draw = () => {
      if (!canvasRef.current || !analyserRef.current || !dataArrayRef.current) return;

      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      analyserRef.current.getByteFrequencyData(dataArrayRef.current);

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const barCount = 12; // Fixed number of bars for a cleaner look
      const barWidth = 4;
      const barGap = 4;
      const totalWidth = (barWidth + barGap) * barCount - barGap;
      const startX = (canvas.width - totalWidth) / 2;

      for (let i = 0; i < barCount; i++) {
        // Average multiple frequency bins for each bar
        const binIndex = Math.floor(i * (dataArrayRef.current.length / 2) / barCount);
        const value = dataArrayRef.current[binIndex];

        const barHeight = isPlaying 
          ? Math.max(4, (value / 255) * canvas.height * 0.9)
          : 4; // Minimal height when paused

        const x = startX + i * (barWidth + barGap);
        const y = (canvas.height - barHeight) / 2;

        // Gradient for a glassy look
        const gradient = ctx.createLinearGradient(0, y, 0, y + barHeight);
        gradient.addColorStop(0, color);
        gradient.addColorStop(1, `${color}44`);

        ctx.fillStyle = gradient;
        ctx.shadowBlur = 8;
        ctx.shadowColor = `${color}33`;

        // Use a rounded rectangle path
        ctx.beginPath();
        if (ctx.roundRect) {
          ctx.roundRect(x, y, barWidth, barHeight, 2);
        } else {
          ctx.rect(x, y, barWidth, barHeight);
        }
        ctx.fill();
      }

      animationRef.current = requestAnimationFrame(draw);
    };

    if (isPlaying) {
      setupAudio();
      if (contextRef.current?.state === 'suspended') {
        contextRef.current.resume();
      }
      animationRef.current = requestAnimationFrame(draw);
    } else {
      // Draw static baseline
      draw();
      cancelAnimationFrame(animationRef.current);
    }

    return () => cancelAnimationFrame(animationRef.current);
  }, [isPlaying, audioRef, color]);

  return (
    <canvas 
      ref={canvasRef} 
      width={120} 
      height={40} 
      className="transition-all duration-500"
    />
  );
};

