              <div className="flex items-center gap-4 w-full md:w-auto min-w-0">
                <div className={`w-14 h-14 rounded-2xl bg-gradient-to-br ${activeSermon.color} shrink-0 flex items-center justify-center border border-white/30 shadow-inner relative overflow-hidden group/thumb`}>
                  <Mic2 size={20} className="text-white/80 group-hover/thumb:scale-125 transition-transform" />
                  {isPlaying && (
                    <div className="absolute inset-0 bg-blue-500/10 flex items-center justify-center">
                       <AudioVisualizer isPlaying={true} audioRef={audioRef} color="#ffffff" />
                    </div>
