                </div>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-6">
                    <button onClick={() => skipTime(-15)} className="text-black/40 dark:text-white/40 hover:text-blue-600 dark:hover:text-blue-400 transition-colors p-2 hover:bg-black/5 rounded-full"><SkipBack size={22} /></button>
                    <button onClick={() => setIsPlaying(!isPlaying)} className="w-14 h-14 bg-black dark:bg-white text-white dark:text-black rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-xl">
                      {isPlaying ? <Pause size={24} className="fill-current" /> : <Play size={24} className="fill-current ml-1" />}
                    </button>
                    <button onClick={() => skipTime(15)} className="text-black/40 dark:text-white/40 hover:text-blue-600 dark:hover:text-blue-400 transition-colors p-2 hover:bg-black/5 rounded-full"><SkipForward size={22} /></button>
                  </div>
                  <div className="flex items-center gap-4">
                    <div className="hidden sm:flex items-center gap-1.5 bg-black/5 dark:bg-white/5 p-1 rounded-xl">
                      {[1, 1.5, 2].map(speed => (
                        <button 
                          key={speed} 
                          onClick={() => setPlaybackSpeed(speed)} 
                          className={`px-3 py-1.5 rounded-lg text-[10px] font-black transition-all ${playbackSpeed === speed ? 'bg-white dark:bg-white/20 text-blue-600 dark:text-white shadow-sm' : 'text-black/40 dark:text-white/40 hover:text-black dark:hover:text-white'}`}
                        >
                          {speed}x
                        </button>
                      ))}
                    </div>
                    <div className="h-4 w-[1px] bg-black/10 dark:border-white/10 hidden sm:block" />
                    <button className="p-2 text-black/40 dark:text-white/40 hover:text-blue-600 dark:hover:text-blue-400 transition-colors group/vol">
                      <Volume2 size={20} className="group-hover/vol:scale-110 transition-transform" />
                    </button>
