            {navItems.map((item) => {
              const isActive = location.pathname === item.path;
              return (
                <Link
                  key={item.path}
                  to={item.path}
                  className={`relative px-4 py-2 rounded-xl transition-all duration-500 text-xs font-bold uppercase tracking-wide group/tab outline-none whitespace-nowrap
